export type Provider = 'anthropic' | 'openai' | 'google' | 'mistral' | 'bedrock'
export interface ClientConfig { provider: Provider; model: string; apiKey?: string; oauth?: OAuthConfig }
export interface Client {
  stream(req: StreamRequest): Promise<StreamHandle>
  streamSimple(req: { messages: Message[] }): Promise<StreamHandle>
  listModels(): Promise<ModelInfo[]>
  readonly usage: UsageMeter
}
export function createClient(config: ClientConfig): Client

export type StreamEvent =
  | { type: 'text_delta'; text: string }
  | { type: 'tool_call'; id: string; name: string; arguments: unknown }
  | { type: 'tool_call_delta'; id: string; argumentsDelta: string }
  | { type: 'stop'; reason: 'end' | 'tool' | 'length'; usage: Usage }
export interface Usage { inputTokens: number; outputTokens: number; costUsd: number }
// NOTE: tool_call_delta carries PARTIAL JSON; arguments is only complete on the
// matching tool_call emitted just before stop. Do not JSON.parse a delta alone.

export interface UsageMeter {
  readonly lastCall: Usage | null
  readonly total: Usage
  reset(): void
}
// Usage.costUsd is computed from provider price tables in dist/pricing.json,
// updated per release. Accumulates across stream() calls until reset().
